+package io.jenkins.plugins.analysis.warnings;
+
+import org.jenkinsci.test.acceptance.po.Control;
+import org.openqa.selenium.JavascriptExecutor;
+import org.openqa.selenium.WebDriver;
+import org.openqa.selenium.WebDriverException;
+import org.openqa.selenium.WebElement;
+
+/**
+ * Utility methods for Jenkins form controls.
+ */
+final class FormControlUtil {
+    static boolean isChecked(final Control control) {
+        return control.resolve().isSelected();
+    }
+
+    static void setCheckBox(final WebDriver driver, final Control control, final boolean checked) {
+        setSelected(driver, control.resolve(), checked);
+    }
+
+    static void selectRadioButton(final WebDriver driver, final WebElement radioButton) {
+        setSelected(driver, radioButton, true);
+    }
+
+    private static void setSelected(final WebDriver driver, final WebElement input, final boolean selected) {
+        if (input.isSelected() != selected) {
+            clickVisibleControl(driver, input);
+        }
+        if (input.isSelected() != selected) {
+            setSelectedWithJavaScript(driver, input, selected);
+        }
+    }
+
+    private static void clickVisibleControl(final WebDriver driver, final WebElement input) {
+        if (driver instanceof JavascriptExecutor) {
+            try {
+                ((JavascriptExecutor) driver).executeScript(
+                        "var input = arguments[0];"
+                                + "var label = input.closest('label');"
+                                + "if (!label && input.id) {"
+                                + "  var labels = document.querySelectorAll('label[for]');"
+                                + "  for (var i = 0; i < labels.length; i++) {"
+                                + "    if (labels[i].getAttribute('for') === input.id) {"
+                                + "      label = labels[i];"
+                                + "      break;"
+                                + "    }"
+                                + "  }"
+                                + "}"
+                                + "if (!label) {"
+                                + "  var container = input.closest('.jenkins-checkbox, .jenkins-radio, .setting-main');"
+                                + "  label = container ? container.querySelector('label') : null;"
+                                + "}"
+                                + "(label || input).click();",
+                        input);
+                return;
+            }
+            catch (WebDriverException ignored) {
+                // Fall back to Selenium's native click below.
+            }
+        }
+
+        input.click();
+    }
+
+    private static void setSelectedWithJavaScript(final WebDriver driver, final WebElement input,
+            final boolean selected) {
+        if (driver instanceof JavascriptExecutor) {
+            ((JavascriptExecutor) driver).executeScript(
+                    "arguments[0].checked = arguments[1];"
+                            + "arguments[0].dispatchEvent(new Event('input', {bubbles: true}));"
+                            + "arguments[0].dispatchEvent(new Event('change', {bubbles: true}));",
+                    input, selected);
+        }
+    }
+
+    private FormControlUtil() {
+        // prevents instantiation
+    }
+}
